{"file_path":"safety_evals/loader.py","content":""""AI alignment evaluation: monitor flag statistics over model transcripts."""


def parse_transcript_log(lines):
    """Parse log lines into transcripts. See SPEC.md section 4."""
    out = []
    flags = {"1": True, "0": False, "": None}
    for line_number, line in enumerate(lines, 1):
        stripped = line.strip()
        if not stripped or stripped.startswith("#"):
            continue
        fields = [field.strip() for field in line.split(",")]
        if len(fields) != 3:
            raise ValueError(f"line {line_number}: expected three fields")
        id_, day, flag = fields
        try:
            day = int(day)
        except ValueError as exc:
            raise ValueError(f"line {line_number}: invalid day") from exc
        if flag not in flags:
            raise ValueError(f"line {line_number}: invalid flagged value")
        out.append({"id": id_, "day": day, "flagged": flags[flag]})
    return out


def dedupe_transcripts(events):
    """Remove duplicate transcripts. See SPEC.md section 5."""
    seen = {}
    for e in events:
        seen[e["id"]] = e
    return sorted(seen.values(), key=lambda e: (e["day"], e["id"]))


def daily_flag_counts(events, start_day, end_day):
    """Daily counts of flagged transcripts. See SPEC.md section 6."""
    counts = [0] * max(0, end_day - start_day + 1)
    for e in events:
        if e["flagged"] is True and start_day <= e["day"] <= end_day:
            counts[e["day"] - start_day] += 1
    return counts
