{"file_path":"tests/test_spec.py","content":"import pytest

from safety_evals.loader import daily_flag_counts, dedupe_transcripts, parse_transcript_log
from safety_evals.metrics import (
    flag_rate_by_group,
    flags_in_window,
    longest_flag_streak,
    monitor_flag_rate,
    pooled_flag_rate,
)
from safety_evals.report import monitor_summary, top_flagged_groups


def event(id_, day, flagged):
    return {"id": id_, "day": day, "flagged": flagged}


def test_monitor_flag_rate_none_counts_in_denominator():
    assert monitor_flag_rate([event("a", 1, True), event("b", 1, None), event("c", 1, False)]) == 1 / 3
    assert monitor_flag_rate([event("a", 1, None)]) == 0.0
    assert monitor_flag_rate([]) == 0.0


def test_pooled_flag_rate_weights_transcripts_and_handles_empty_groups():
    groups = {"small": [event("a", 1, True)], "large": [event(str(i), 1, False) for i in range(3)], "empty": []}
    assert pooled_flag_rate(groups) == 0.25
    assert pooled_flag_rate({"empty": []}) == 0.0
    assert pooled_flag_rate({}) == 0.0


def test_flags_in_window():
    assert flags_in_window([1, 2, 3], 1) == 3
    assert flags_in_window([1, 2, 3], 2) == 5
    assert flags_in_window([1, 2, 3], 0) == 0
    assert flags_in_window([1, 2, 3], 10) == 6
    assert flags_in_window([], 2) == 0


def test_parse_fields_and_skip_lines():
    lines = ["  ", "  # comment,with,commas", "  a  ,  -2 , 1 ", "b,3, 0 ", "c, 4,  "]
    assert parse_transcript_log(lines) == [event("a", -2, True), event("b", 3, False), event("c", 4, None)]


@pytest.mark.parametrize("line", ["a,1", "a,1,1,extra", "a,no-day,1"])
def test_parse_errors_include_original_line_number(line):
    with pytest.raises(ValueError, match=r"line 3\b"):
        parse_transcript_log(["# comment", " ", line])


def test_dedupe_keeps_last_record_per_id_and_sorts_by_day_then_id():
    events = [event("a", 1, True), event("b", 2, True), event("a", 3, None), event("c", 2, False), event("b", 2, False)]
    assert dedupe_transcripts(events) == [events[4], events[3], events[2]]
    assert dedupe_transcripts([]) == []


def test_daily_flag_counts_fills_gaps_and_respects_range():
    events = [event("a", 0, True), event("b", 2, True), event("c", 2, True), event("d", 3, None), event("e", 4, False), event("f", 6, True)]
    assert daily_flag_counts(events, 1, 5) == [0, 2, 0, 0, 0]
    assert daily_flag_counts(events, 3, 2) == []
    assert daily_flag_counts([], 1, 3) == [0, 0, 0]


def test_monitor_summary_uses_calendar_days_weighted_rate_and_nonempty_groups():
    groups = {"a": [event("a", 1, True)], "b": [event(str(i), 5, False) for i in range(5)], "empty": []}
    assert monitor_summary(groups, 2) == {"rate": 0.167, "recent": 0, "groups": 2}
    assert monitor_summary(groups, 5)["recent"] == 1
    assert monitor_summary(groups, 0)["recent"] == 0
    assert monitor_summary({"empty": []}, 2) == {"rate": 0.0, "recent": 0, "groups": 0}
    assert monitor_summary({}, 2) == {"rate": 0.0, "recent": 0, "groups": 0}


def test_top_flagged_groups_excludes_empty_and_breaks_ties_by_name():
    groups = {"z": [event("z", 1, True)], "empty": [], "a": [event("a", 1, True)], "b": [event("b", 1, False)]}
    assert top_flagged_groups(groups, 5) == ["a", "z", "b"]
    assert top_flagged_groups(groups, 1) == ["a"]
    assert top_flagged_groups(groups, 0) == []


def test_flag_rate_by_group_sorted_and_empty_is_none():
    groups = {"z": [], "b": [event("b", 1, None)], "a": [event("a", 1, True)]}
    rates = flag_rate_by_group(groups)
    assert list(rates) == ["a", "b", "z"]
    assert rates == {"a": 1.0, "b": 0.0, "z": None}


def test_longest_flag_streak_resets_on_nonpositive_counts():
    assert longest_flag_streak([1, 2, 0, 3, -1, 4, 5, 6]) == 3
    assert longest_flag_streak([0, -1]) == 0
    assert longest_flag_streak([]) == 0
